const body = $input.first().json.body || {};
const id = parseInt(body.id, 10);
if (!Number.isInteger(id)) throw new Error('"id" must be an integer.');

// Partial update — body text and the pinned flag can each be sent
// independently (toggling pin from the note list shouldn't require
// resending the full note text, and editing the text shouldn't
// accidentally unpin/pin it).
const noteBody = body.body === undefined ? null : body.body;
const isPinned = body.is_pinned === undefined ? null : (body.is_pinned === true || body.is_pinned === 'true');

return [{ json: { id, noteBody, isPinned } }];
